def calculate_S(N):
    """Calculates S(N) = sum_{a=1}^N sum_{b=1}^N floor(ab / (N+1))"""
    S_N = 0
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            S_N += (a * b) // (N + 1)
    return S_N

def calculate_T(N):
    """Calculates T(N) = (N^3 - N^2 + 2) / 4"""
    return (N**3 - N**2 + 2) / 4

N_values = [1, 2, 3, 4, 5]
results = {}
for N in N_values:
    S_N = calculate_S(N)
    T_N = calculate_T(N)
    is_equal = S_N == T_N
    results[N] = {
        "S(N)": S_N,
        "T(N)": T_N,
        "Equal": is_equal
    }

for N, res in results.items():
    print(f"N={N}: S(N)={res['S(N)']}, T(N)={res['T(N)']}, Equal={res['Equal']}")

